import java.sql.*; public class _Q2 { public static void main(String[] a) throws Exception { Connection c = DriverManager.getConnection("jdbc:sqlserver://127.0.0.1:1433;databaseName=HSDZ_MES;encrypt=false", "yinjia", "Yinjia@2026"); Statement s = c.createStatement(); ResultSet r = s.executeQuery("SELECT panel_code, panel_name FROM yj_panel WHERE panel_code IN ('DAY_REPORT','FEED_CONFIRM','MIX_RECORD','GRAN_RECORD','QC_RECORD','WH_RECORD','PACK_CONFIRM','EQUIP_CHECK','MAINT_PLAN','SAMPLE_REQ','ROD_RETURN') ORDER BY panel_code"); int n = 0; while (r.next()) { n++; System.out.println(r.getString(1) + " " + r.getString(2)); } System.out.println("panels: " + n + "/11"); r = s.executeQuery("SELECT COUNT(DISTINCT panel_code) FROM yj_field WHERE panel_code LIKE '%REPORT' OR panel_code IN ('FEED_CONFIRM','MIX_RECORD','GRAN_RECORD','QC_RECORD','WH_RECORD','PACK_CONFIRM','EQUIP_CHECK','MAINT_PLAN','SAMPLE_REQ','ROD_RETURN')"); r.next(); System.out.println("field panels: " + r.getInt(1)); } }